/* ================= TITIPAN TOKO (stok yang dititip / disimpan di toko lain) ================= */
let titipSearch = '';
function tokoList(){ if(!Array.isArray(DATA.tokoMitra)) DATA.tokoMitra = []; return DATA.tokoMitra; }
function isTitip(s){ return !!(s && s.lokasi && s.lokasi.toko); }
function lamaHari(t){ const m = String(t||'').match(/^(\d{4})-(\d{2})-(\d{2})/); if(!m) return null; const d = new Date(+m[1], +m[2]-1, +m[3]); return Math.max(0, Math.floor((Date.now() - d.getTime())/86400000)); }
function catatLokasi(s, ke, tanggal, catatan){ (s.riwayatLokasi = s.riwayatLokasi || []).push({tanggal, dari: isTitip(s) ? s.lokasi.toko : 'Toko sendiri', ke: ke || 'Toko sendiri', catatan: catatan||''}); }
function waLink(no){ const d = String(no||'').replace(/\D/g,'').replace(/^0/,'62'); return d ? 'https://wa.me/'+d : ''; }
function modalBeliUnit(s){ return (Number(s.hargaModal)||0) + totalBiaya(s); }

function renderTitip(c, ta){
  ta.innerHTML = `<button class="btn" id="addTokoBtn">+ Toko Mitra</button> <button class="btn btn-primary" id="titipBtn">+ Titipkan Unit</button>`;
  ta.querySelector('#addTokoBtn').onclick = () => openTokoModal();
  ta.querySelector('#titipBtn').onclick = () => openTitipModal();
  const tokos = tokoList();
  const aktif = DATA.stock.filter(s => isTitip(s) && s.status !== 'Sold');
  const terjualDiToko = DATA.stock.filter(s => isTitip(s) && s.status === 'Sold');
  const q = titipSearch.trim().toLowerCase();
  const match = s => !q || [s.id, s.merek, s.tipe, s.noSeri].some(v => String(v||'').toLowerCase().includes(q));
  const names = [...new Set([...tokos.map(t=>t.nama), ...aktif.map(s=>s.lokasi.toko)])];
  const lama30 = aktif.filter(s => (lamaHari(s.lokasi.tanggal)||0) > 30).length;
  const card = (l,v,sub,color) => `<div class="stat-card"><div class="lbl">${l}</div><div class="val" style="font-size:19px${color?';color:'+color:''}">${v}</div><div class="sub">${sub}</div></div>`;
  const panels = names.map(n => {
    const t = tokos.find(x=>x.nama===n) || {nama:n};
    const units = aktif.filter(s => s.lokasi.toko === n);
    const tokoCocok = !q || n.toLowerCase().includes(q);
    const shown = tokoCocok ? units : units.filter(match);
    if(q && !tokoCocok && !shown.length) return '';
    const rows = shown.slice().sort((a,b)=>String(a.lokasi.tanggal||'').localeCompare(String(b.lokasi.tanggal||''))).map(s => { const h = lamaHari(s.lokasi.tanggal); return `<tr data-id-row="${esc(s.id)}">
      <td class="mono">${esc(s.id)}</td>
      <td><b>${esc(s.merek)} ${esc(s.tipe)}</b><div class="dim" style="font-size:11.5px">${esc([s.processor,s.ram,s.ssd].filter(Boolean).join(' · '))}${s.noSeri?' · SN '+esc(s.noSeri):''}</div></td>
      <td>${statusBadge(s.status)}</td>
      <td class="mono">${esc(s.lokasi.tanggal||'-')}</td>
      <td class="mono" style="color:${h>30?'var(--danger)':'inherit'}">${h===null?'-':h+' hari'}</td>
      <td class="mono">${Number(s.hargaJual)?rupiah(hargaAkhir(s)):'<span class="dim">belum</span>'}</td>
      <td class="mono">${Number(s.lokasi.hargaSetor)?rupiah(s.lokasi.hargaSetor):'<span class="dim">-</span>'}</td>
      <td class="dim" style="font-size:12px">${esc(s.lokasi.catatan||'')}</td>
      <td style="white-space:nowrap"><button class="btn" data-tt-move="${esc(s.id)}">Pindah</button> <button class="btn" data-tt-back="${esc(s.id)}">Tarik</button> <button class="btn btn-primary" data-tt-sold="${esc(s.id)}">Terjual</button></td></tr>`; }).join('');
    const wa = waLink(t.wa);
    const info = [t.pic ? 'PIC '+esc(t.pic) : '', t.wa ? (wa ? `<a href="${wa}" target="_blank" rel="noopener">WA ${esc(t.wa)}</a>` : esc(t.wa)) : '', esc(t.alamat||''), t.catatan ? 'Kesepakatan: '+esc(t.catatan) : ''].filter(Boolean).join(' · ');
    return `<div class="panel" style="margin-bottom:16px">
      <div style="display:flex;justify-content:space-between;align-items:flex-start;gap:10px;flex-wrap:wrap;margin-bottom:10px">
        <div><h3 style="margin:0">⌂ ${esc(n)}</h3><div class="dim" style="font-size:12.5px;margin-top:4px">${info || 'Data toko belum lengkap — klik Edit Toko'}</div></div>
        <div style="text-align:right"><div class="mono"><b>${units.length}</b> unit · modal ${rupiah(units.reduce((a,s)=>a+modalBeliUnit(s),0))}</div>
          <div style="margin-top:6px;display:flex;gap:6px;justify-content:flex-end;flex-wrap:wrap"><button class="btn" data-tt-addto="${esc(n)}">+ Titip ke sini</button><button class="btn" data-tt-edit="${esc(n)}">Edit Toko</button>${units.length?'':`<button class="icon-btn btn-danger" data-tt-del="${esc(n)}" title="Hapus toko">✕</button>`}</div></div>
      </div>
      ${units.length ? `<div class="table-wrap"><table><thead><tr><th>ID</th><th>Laptop</th><th>Status</th><th>Tgl Titip</th><th>Lama</th><th>Harga Jual</th><th>Harga Setor</th><th>Catatan</th><th>Aksi</th></tr></thead><tbody>${rows || '<tr><td colspan="9" class="dim">Tidak ada yang cocok dengan pencarian.</td></tr>'}</tbody></table></div>` : '<div class="empty"><p>Belum ada unit yang dititip di toko ini.</p></div>'}
    </div>`;
  }).join('');
  const hist = DATA.stock.flatMap(s => (s.riwayatLokasi||[]).map(r => Object.assign({id:s.id, laptop:s.merek+' '+s.tipe}, r))).sort((a,b)=>String(b.tanggal).localeCompare(String(a.tanggal))).slice(0,20);
  c.innerHTML = `
    <div class="grid-stats" style="margin-bottom:16px">
      ${card('Unit Dititip', aktif.length, `di ${new Set(aktif.map(s=>s.lokasi.toko)).size} toko · ${DATA.stock.filter(s=>s.status!=='Sold').length - aktif.length} unit di toko sendiri`)}
      ${card('Toko Mitra', names.length, 'tempat titip / simpan stok')}
      ${card('Nilai Modal Dititip', rupiah(aktif.reduce((a,s)=>a+modalBeliUnit(s),0)), 'harga beli + biaya service')}
      ${card('Nilai Jual Dititip', rupiah(aktif.reduce((a,s)=>a+(Number(s.hargaJual)?hargaAkhir(s):0),0)), aktif.filter(s=>!Number(s.hargaJual)).length + ' unit belum ada harga jual')}
      ${card('Titip > 30 Hari', lama30, 'perlu dicek / ditarik', lama30?'var(--danger)':'')}
      ${card('Terjual di Toko Mitra', terjualDiToko.length, 'unit Sold yang dititip di toko mitra')}
    </div>
    <div class="toolbar"><input class="search" id="titipSearch" placeholder="Cari ID, merek, tipe, SN, atau nama toko..." value="${esc(titipSearch)}"></div>
    ${panels || `<div class="panel"><div class="empty"><div class="ic">⌂</div><p>Belum ada unit yang dititip. Klik <b>+ Toko Mitra</b> untuk mendaftarkan toko, lalu <b>+ Titipkan Unit</b>.</p></div></div>`}
    ${hist.length ? `<div class="panel"><h3>Riwayat Perpindahan Unit</h3><div class="table-wrap"><table><thead><tr><th>Tanggal</th><th>ID</th><th>Laptop</th><th>Dari</th><th>Ke</th><th>Catatan</th></tr></thead><tbody>${hist.map(r=>`<tr><td class="mono">${esc(r.tanggal)}</td><td class="mono dim">${esc(r.id)}</td><td>${esc(r.laptop)}</td><td>${esc(r.dari)}</td><td><b>${esc(r.ke)}</b></td><td class="dim">${esc(r.catatan||'')}</td></tr>`).join('')}</tbody></table></div></div>` : ''}`;
  const si = c.querySelector('#titipSearch');
  si.oninput = () => { titipSearch = si.value; const pos = si.selectionStart; renderTitip(c, ta); const n = c.querySelector('#titipSearch'); n.focus(); try{ n.setSelectionRange(pos,pos); }catch(_){} };
  c.querySelectorAll('[data-tt-move]').forEach(b => b.onclick = () => openTitipModal([b.dataset.ttMove]));
  c.querySelectorAll('[data-tt-addto]').forEach(b => b.onclick = () => openTitipModal(null, b.dataset.ttAddto));
  c.querySelectorAll('[data-tt-edit]').forEach(b => b.onclick = () => openTokoModal(b.dataset.ttEdit));
  c.querySelectorAll('[data-tt-del]').forEach(b => b.onclick = async () => {
    const n = b.dataset.ttDel; const ok = await confirmChange('Hapus toko mitra?', [['Toko mitra', n, '(dihapus)']]); if(!ok) return;
    DATA.tokoMitra = tokoList().filter(t=>t.nama!==n); await persist(); showToast('Toko mitra dihapus'); renderTitip(c, ta); });
  c.querySelectorAll('[data-tt-back]').forEach(b => b.onclick = async () => {
    const s = DATA.stock.find(x=>x.id===b.dataset.ttBack); if(!s || !isTitip(s)) return;
    const ok = await confirmChange(`Tarik ${s.id} kembali ke toko sendiri?`, [[`Lokasi — ${s.merek} ${s.tipe}`, s.lokasi.toko, 'Toko sendiri']]); if(!ok) return;
    catatLokasi(s, '', localYMD(), 'ditarik kembali'); delete s.lokasi; await persist(); showToast(`${s.id} sudah kembali ke toko sendiri`); renderTitip(c, ta); });
  c.querySelectorAll('[data-tt-sold]').forEach(b => b.onclick = () => { openSaleModal(b.dataset.ttSold); showToast('Catat penjualan unit yang laku di toko mitra'); });
}

function openTokoModal(nama){
  const t = tokoList().find(x=>x.nama===nama) || {};
  document.getElementById('modalBox').innerHTML = `<h3>${nama?'Edit':'Tambah'} Toko Mitra</h3>
    <div class="form-grid">
      <div class="field full"><label>Nama Toko</label><input id="tk_nama" value="${esc(t.nama||nama||'')}" placeholder="contoh: Toko Sinar Komputer"></div>
      <div class="field"><label>Nama Pemilik / PIC</label><input id="tk_pic" value="${esc(t.pic||'')}"></div>
      <div class="field"><label>No. WhatsApp</label><input id="tk_wa" inputmode="numeric" value="${esc(t.wa||'')}" placeholder="08xxxxxxxxxx"></div>
      <div class="field full"><label>Alamat</label><input id="tk_alamat" value="${esc(t.alamat||'')}"></div>
      <div class="field full"><label>Kesepakatan / Catatan</label><input id="tk_catatan" value="${esc(t.catatan||'')}" placeholder="komisi, sistem setoran, jangka waktu titip..."></div>
    </div>
    <div class="modal-actions"><button class="btn btn-ghost" id="tk_cancel">Batal</button><button class="btn btn-primary" id="tk_save">Simpan</button></div>`;
  const ov = document.getElementById('overlay'); ov.classList.add('show');
  const $ = x => document.getElementById(x);
  $('tk_cancel').onclick = () => ov.classList.remove('show');
  $('tk_save').onclick = async () => {
    const baru = $('tk_nama').value.trim(); if(!baru){ alert('Nama toko wajib diisi'); return; }
    const list = tokoList();
    if(baru !== nama && list.some(x=>x.nama===baru)){ alert('Nama toko sudah terdaftar'); return; }
    const obj = {nama:baru, pic:$('tk_pic').value.trim(), wa:$('tk_wa').value.trim(), alamat:$('tk_alamat').value.trim(), catatan:$('tk_catatan').value.trim()};
    const i = list.findIndex(x=>x.nama===nama);
    if(i >= 0) list[i] = obj; else list.push(obj);
    if(nama && baru !== nama) DATA.stock.forEach(s => { if(isTitip(s) && s.lokasi.toko === nama) s.lokasi.toko = baru; });
    await persist(); ov.classList.remove('show'); showToast('Toko mitra disimpan'); render();
  };
}

function openTitipModal(presetIds, presetToko){
  const tokos = tokoList();
  const sel = new Set(presetIds||[]);
  let q = '';
  const first = presetIds && presetIds.length === 1 ? DATA.stock.find(s=>s.id===presetIds[0]) : null;
  document.getElementById('modalBox').innerHTML = `<h3>${first && isTitip(first) ? 'Pindahkan Unit ke Toko Lain' : 'Titipkan Unit ke Toko Lain'}</h3>
    <div class="form-grid">
      <div class="field"><label>Toko Tujuan</label><select id="tt_toko"><option value="">— Pilih toko —</option>${tokos.map(t=>`<option value="${esc(t.nama)}" ${t.nama===presetToko?'selected':''}>${esc(t.nama)}</option>`).join('')}<option value="__new">+ Toko baru...</option></select></div>
      <div class="field"><label>Tanggal Titip</label><input id="tt_tgl" type="date" value="${localYMD()}"></div>
      <div class="field full" id="tt_newWrap" style="display:none"><label>Nama Toko Baru</label><input id="tt_new" placeholder="contoh: Toko Sinar Komputer"></div>
      <div class="field"><label>Harga Setor ke Kita (opsional)</label><input id="tt_setor" type="number" min="0" placeholder="harga yang disetor toko bila laku"></div>
      <div class="field"><label>Catatan</label><input id="tt_cat" placeholder="kondisi, kelengkapan, komisi..."></div>
      <div class="field full"><label>Pilih Unit <span class="dim" id="tt_count"></span></label>
        <input id="tt_q" class="search" placeholder="Cari ID, merek, tipe, SN..." style="margin-bottom:8px">
        <div id="tt_list" style="max-height:260px;overflow:auto;border:1px solid var(--border,#e3e7ef);border-radius:10px;padding:4px 8px"></div></div>
    </div>
    <div class="modal-actions"><button class="btn btn-ghost" id="tt_cancel">Batal</button><button class="btn btn-primary" id="tt_save">Simpan</button></div>`;
  const ov = document.getElementById('overlay'); ov.classList.add('show');
  const $ = x => document.getElementById(x);
  const count = () => { $('tt_count').textContent = sel.size ? `(${sel.size} dipilih)` : ''; };
  const drawList = () => {
    const qq = q.trim().toLowerCase();
    const list = DATA.stock.filter(s => s.status !== 'Sold' && (sel.has(s.id) || !qq || [s.id,s.merek,s.tipe,s.noSeri].some(v=>String(v||'').toLowerCase().includes(qq)))).slice(0,200);
    $('tt_list').innerHTML = list.map(s => `<label style="display:flex;gap:8px;align-items:center;padding:7px 2px;border-bottom:1px dashed var(--border,#e3e7ef);font-size:13px;cursor:pointer">
      <input type="checkbox" data-tt="${esc(s.id)}" ${sel.has(s.id)?'checked':''}><span class="mono dim" style="width:54px">${esc(s.id)}</span>
      <span style="flex:1">${esc(s.merek)} ${esc(s.tipe)}</span><span class="dim" style="font-size:11.5px">${isTitip(s)?'📍 '+esc(s.lokasi.toko):'Toko sendiri'} · ${esc(s.status)}</span></label>`).join('')
      || '<div class="dim" style="padding:8px">Tidak ada unit yang cocok.</div>';
    $('tt_list').querySelectorAll('[data-tt]').forEach(cb => cb.onchange = () => { cb.checked ? sel.add(cb.dataset.tt) : sel.delete(cb.dataset.tt); count(); });
    count();
  };
  $('tt_q').oninput = () => { q = $('tt_q').value; drawList(); };
  $('tt_toko').onchange = () => { $('tt_newWrap').style.display = $('tt_toko').value === '__new' ? '' : 'none'; };
  if(first && isTitip(first) && Number(first.lokasi.hargaSetor)) $('tt_setor').value = first.lokasi.hargaSetor;
  $('tt_cancel').onclick = () => ov.classList.remove('show');
  drawList();
  $('tt_save').onclick = async () => {
    let toko = $('tt_toko').value;
    if(toko === '__new'){ toko = $('tt_new').value.trim(); if(!toko){ alert('Isi nama toko baru'); return; } }
    if(!toko){ alert('Pilih toko tujuan'); return; }
    if(!sel.size){ alert('Pilih minimal 1 unit'); return; }
    const tgl = $('tt_tgl').value || localYMD(), setor = Number($('tt_setor').value)||0, cat = $('tt_cat').value.trim();
    const units = [...sel].map(id => DATA.stock.find(s=>s.id===id)).filter(s => s && !(isTitip(s) && s.lokasi.toko === toko));
    if(!units.length){ alert('Unit yang dipilih sudah berada di ' + toko); return; }
    const rows = units.slice(0,12).map(s => [`${s.id} ${s.merek} ${s.tipe}`, isTitip(s) ? s.lokasi.toko : 'Toko sendiri', toko]);
    if(units.length > 12) rows.push([`+${units.length-12} unit lainnya`, '', toko]);
    const ok = await confirmChange(`Titipkan ${units.length} unit ke ${toko}?`, rows); if(!ok) return;
    if(!tokoList().some(t=>t.nama===toko)) tokoList().push({nama:toko});
    units.forEach(s => { catatLokasi(s, toko, tgl, cat); s.lokasi = {toko, tanggal:tgl, hargaSetor: setor || 0, catatan:cat}; });
    await persist(); ov.classList.remove('show'); showToast(`${units.length} unit dicatat dititip di ${toko}`); render();
  };
}

